import { handleAnalyticsRoute, type AnalyticsContext } from "./analyticsApi";

/**
 * Preview-only seeding for pull-request preview deployments.
 *
 * Preview builds have no indexer or analytics API behind them. When
 * `VITE_PREVIEW_SEED=true` (set only by the preview workflow) this module loads
 * the static `preview-seed.json` generated by `scripts/seed-preview.mjs` and
 * serves the analytics endpoints from it by intercepting same-origin `fetch`
 * calls, reusing the exact route handlers the e2e suite exercises.
 *
 * Outside preview builds {@link isPreviewSeedEnabled} is false and
 * {@link installPreviewSeed} is a no-op, so normal deployments are unaffected.
 */

export const PREVIEW_SEED_FILE = "preview-seed.json";

export function isPreviewSeedEnabled(): boolean {
  return String(import.meta.env.VITE_PREVIEW_SEED ?? "") === "true";
}

export function previewSeedUrl(): string {
  const base = import.meta.env.BASE_URL || "/";
  return `${base.replace(/\/+$/, "")}/${PREVIEW_SEED_FILE}`;
}

async function loadPreviewSeed(): Promise<AnalyticsContext | null> {
  try {
    const response = await fetch(previewSeedUrl(), {
      headers: { Accept: "application/json" },
    });
    if (!response.ok) return null;
    return (await response.json()) as AnalyticsContext;
  } catch {
    return null;
  }
}

function requestUrl(input: RequestInfo | URL): URL | null {
  try {
    const href =
      input instanceof Request
        ? input.url
        : input instanceof URL
          ? input.href
          : String(input);
    return new URL(href, window.location.origin);
  } catch {
    return null;
  }
}

/**
 * Install the preview seed fetch interceptor. Resolves once the seed has been
 * loaded and patched, or immediately when preview seeding is not enabled.
 */
export async function installPreviewSeed(): Promise<void> {
  if (!isPreviewSeedEnabled() || typeof window === "undefined") return;

  const context = await loadPreviewSeed();
  if (!context) return;

  const originalFetch = window.fetch.bind(window);
  window.fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = requestUrl(input);
    const isSeedRequest = url?.pathname.endsWith(`/${PREVIEW_SEED_FILE}`) ?? false;

    if (url && url.origin === window.location.origin && !isSeedRequest) {
      const method =
        (input instanceof Request ? input.method : undefined) ?? init?.method ?? "GET";
      const result = handleAnalyticsRoute(method, url.pathname, url.searchParams, context);
      // Unknown paths (assets, the seed itself, SPA navigation) fall through to
      // the network rather than 404ing here.
      if (result.status !== 404) {
        const payload = "data" in result ? result.data : result.error;
        return new Response(JSON.stringify(payload), {
          status: result.status,
          headers: { "Content-Type": "application/json" },
        });
      }
    }

    return originalFetch(input as RequestInfo, init);
  };
}
